//! Window functions end to end against Spark 4.2 (P2-T055): each case of
//! `tests/fixtures/spark-4.2.0/window-goldens.json` (generated by
//! `tests/scripts/gen_window_goldens.py` from a real Spark run) runs
//! through a session over the fixture's tables, and must give Spark's
//! output names, types, nullability and rows, or Spark's error class and
//! message parameters.
#![cfg(test)]

use std::fmt::Write as _;
use std::path::Path;
use std::sync::Arc;

use arrow_array::cast::AsArray;
use arrow_array::types::{
    Date32Type, Decimal64Type, Decimal128Type, Float64Type, Int32Type, Int64Type,
};
use arrow_array::{
    Array, ArrayRef, Date32Array, Decimal128Array, Float64Array, Int32Array, Int64Array,
    RecordBatch, StringArray,
};
use arrow_schema::{DataType, Field, Schema};
use futures::executor::block_on;
use krishiv_session::Session;
use serde_json::Value;

/// Cases of a later part of P2-T055 (`RANGE` frames with value bounds):
/// they fail with `KRISHIV_UNSUPPORTED_FEATURE` until then.
const PENDING: [&str; 1] = ["range_offset"];

/// Known gaps outside window functions, with the error they give until
/// fixed: constant arguments fold from literals and casts only, so
/// `ntile(1 + 1)` and a frame bound `1 + 1 PRECEDING` are not foldable yet
/// (the analyzer's general constant folding of operators is separate P2b
/// work).
const GAPS: [(&str, &str); 2] = [
    ("ntile_folded", "DATATYPE_MISMATCH.NON_FOLDABLE_INPUT"),
    ("frame_folded_bound", "KRISHIV_UNSUPPORTED_FEATURE"),
];

fn fixture() -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/window-goldens.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

/// `decimal(p,s)` as `(p, s)`.
fn decimal(t: &str) -> Option<(u8, i8)> {
    let inner = t.strip_prefix("decimal(")?.strip_suffix(')')?;
    let (p, s) = inner.split_once(',')?;
    Some((p.trim().parse().ok()?, s.trim().parse().ok()?))
}

/// The unscaled value of decimal text with `scale` digits after the point.
fn unscaled(text: &str, scale: i8) -> i128 {
    let negative = text.starts_with('-');
    let digits = text.trim_start_matches('-');
    let (int, frac) = digits.split_once('.').unwrap_or((digits, ""));
    let mut frac = frac.to_owned();
    frac.extend(std::iter::repeat_n(
        '0',
        usize::try_from(scale).unwrap() - frac.len(),
    ));
    let v: i128 = format!("{int}{frac}").parse().unwrap();
    if negative { -v } else { v }
}

/// A column of Spark type `t` from the fixture's text values.
fn column(t: &str, values: &[Option<&str>]) -> (DataType, ArrayRef) {
    match t {
        "int" => (
            DataType::Int32,
            Arc::new(Int32Array::from_iter(
                values.iter().map(|v| v.map(|v| v.parse::<i32>().unwrap())),
            )),
        ),
        "bigint" => (
            DataType::Int64,
            Arc::new(Int64Array::from_iter(
                values.iter().map(|v| v.map(|v| v.parse::<i64>().unwrap())),
            )),
        ),
        "double" => (
            DataType::Float64,
            Arc::new(Float64Array::from_iter(
                values.iter().map(|v| v.map(|v| v.parse::<f64>().unwrap())),
            )),
        ),
        "string" => (
            DataType::Utf8,
            Arc::new(StringArray::from_iter(values.iter().copied())),
        ),
        "date" => (
            DataType::Date32,
            Arc::new(Date32Array::from_iter(values.iter().map(|v| v.map(days)))),
        ),
        t => {
            // Decimals on the canonical carrier, as tables hold them.
            let (p, s) = decimal(t).unwrap_or_else(|| panic!("fixture type {t}"));
            let a = Decimal128Array::from_iter(values.iter().map(|v| v.map(|v| unscaled(v, s))))
                .with_precision_and_scale(p, s)
                .unwrap();
            (DataType::Decimal128(p, s), Arc::new(a))
        }
    }
}

fn session(g: &Value) -> Session {
    let s = Session::new().unwrap();
    for (name, table) in g["tables"].as_object().unwrap() {
        let rows = table["rows"].as_array().unwrap();
        let mut fields = Vec::new();
        let mut columns = Vec::new();
        for (i, c) in table["columns"].as_array().unwrap().iter().enumerate() {
            let values: Vec<Option<&str>> = rows.iter().map(|r| r[i].as_str()).collect();
            let (t, a) = column(c["type"].as_str().unwrap(), &values);
            fields.push(Field::new(
                c["name"].as_str().unwrap(),
                t,
                c["nullable"].as_bool().unwrap(),
            ));
            columns.push(a);
        }
        let schema = Arc::new(Schema::new(fields));
        let batch = RecordBatch::try_new(Arc::clone(&schema), columns).unwrap();
        s.register_batches(name, schema, vec![batch]).unwrap();
    }
    s
}

/// A result value as the fixture writes it, by Spark type `t`.
fn text(a: &ArrayRef, i: usize) -> Value {
    if a.is_null(i) {
        return Value::Null;
    }
    let s = match a.data_type() {
        DataType::Int32 => a.as_primitive::<Int32Type>().value(i).to_string(),
        DataType::Int64 => a.as_primitive::<Int64Type>().value(i).to_string(),
        DataType::Float64 => {
            // Compared as bits through the fixture's text, parsed back.
            let v = a.as_primitive::<Float64Type>().value(i);
            return Value::String(format!("f64:{}", v.to_bits()));
        }
        DataType::Decimal64(_, s) => {
            plain(i128::from(a.as_primitive::<Decimal64Type>().value(i)), *s)
        }
        DataType::Decimal128(_, s) => plain(a.as_primitive::<Decimal128Type>().value(i), *s),
        DataType::Date32 => iso(a.as_primitive::<Date32Type>().value(i)),
        DataType::Utf8 | DataType::Utf8View | DataType::LargeUtf8 => arrow_cast_string(a, i),
        t => panic!("result type {t}"),
    };
    Value::String(s)
}

fn arrow_cast_string(a: &ArrayRef, i: usize) -> String {
    match a.data_type() {
        DataType::Utf8View => a.as_string_view().value(i).to_owned(),
        DataType::LargeUtf8 => a.as_string::<i64>().value(i).to_owned(),
        _ => a.as_string::<i32>().value(i).to_owned(),
    }
}

/// Days since 1970-01-01 of an ISO date (proleptic Gregorian).
fn days(text: &str) -> i32 {
    let mut parts = text.split('-').map(|p| p.parse::<i64>().unwrap());
    let (y, m, d) = (
        parts.next().unwrap(),
        parts.next().unwrap(),
        parts.next().unwrap(),
    );
    // Howard Hinnant's days_from_civil.
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let mp = (m + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    i32::try_from(era * 146_097 + doe - 719_468).unwrap()
}

/// The ISO text of days since 1970-01-01.
fn iso(days: i32) -> String {
    let z = i64::from(days) + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + i64::from(m <= 2);
    format!("{y:04}-{m:02}-{d:02}")
}

fn plain(v: i128, scale: i8) -> String {
    let digits = v.unsigned_abs().to_string();
    let scale = usize::try_from(scale).unwrap();
    let sign = if v < 0 { "-" } else { "" };
    if scale == 0 {
        return format!("{sign}{digits}");
    }
    let padded = format!("{digits:0>width$}", width = scale + 1);
    let (int, frac) = padded.split_at(padded.len() - scale);
    format!("{sign}{int}.{frac}")
}

/// A fixture value of type `t` as [`text`] writes it.
fn expected(v: &Value, t: &str) -> Value {
    match (v, t) {
        (Value::String(s), "double") => {
            let f: f64 = s.parse().unwrap();
            Value::String(format!("f64:{}", f.to_bits()))
        }
        (v, _) => v.clone(),
    }
}

/// The mismatches of one case, as text (empty when it matches).
fn check(s: &Session, tables: &[&str], case: &Value) -> String {
    let mut out = String::new();
    let conf = s.conf();
    let settings = case["conf"].as_object().unwrap();
    for (k, v) in settings {
        conf.set(k, v.as_str().unwrap()).unwrap();
    }
    let sql = case["sql"].as_str().unwrap();
    let result = block_on(async {
        let df = s.sql(sql).await?;
        let schema = df.schema().await?;
        let batches = df.collect().await?;
        Ok::<_, krishiv_common::error::KrishivError>((schema, batches))
    });
    for k in settings.keys() {
        conf.unset(k).unwrap();
    }
    let id = case["id"].as_str().unwrap();
    if let Some((_, class)) = GAPS.iter().find(|(g, _)| *g == id) {
        match result {
            Err(e) if e.error_class().name() == *class => {}
            other => {
                let _ = writeln!(out, "{id}: known gap changed (update GAPS): {other:?}");
            }
        }
        return out;
    }
    if PENDING.contains(&id) {
        match result {
            Err(e) if e.error_class().name() == "KRISHIV_UNSUPPORTED_FEATURE" => {}
            other => {
                let _ = writeln!(
                    out,
                    "{id}: pending case did not fail as unsupported: {other:?}"
                );
            }
        }
        return out;
    }
    match (case["ok"].as_bool().unwrap(), result) {
        (true, Ok((schema, batches))) => {
            let want = case["output"].as_array().unwrap();
            if schema.fields().len() != want.len() {
                let _ = writeln!(
                    out,
                    "{id}: {} columns, Spark {}",
                    schema.fields().len(),
                    want.len()
                );
                return out;
            }
            let types: Vec<&str> = want.iter().map(|w| w["type"].as_str().unwrap()).collect();
            for (f, w) in schema.fields().iter().zip(want) {
                let ty = krishiv_types::DataType::from_arrow(f.data_type())
                    .map(|t| t.simple_string())
                    .unwrap_or_default();
                if f.name() != w["name"].as_str().unwrap()
                    || ty != w["type"].as_str().unwrap()
                    || f.is_nullable() != w["nullable"].as_bool().unwrap()
                {
                    let _ = writeln!(
                        out,
                        "{id}: column {}:{ty}:{} vs Spark {}",
                        f.name(),
                        f.is_nullable(),
                        w
                    );
                }
            }
            let mut got: Vec<Vec<Value>> = Vec::new();
            for b in &batches {
                for i in 0..b.num_rows() {
                    got.push(b.columns().iter().map(|c| text(c, i)).collect());
                }
            }
            let mut want_rows: Vec<Vec<Value>> = case["rows"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| {
                    r.as_array()
                        .unwrap()
                        .iter()
                        .zip(&types)
                        .map(|(v, t)| expected(v, t))
                        .collect()
                })
                .collect();
            let key = |r: &Vec<Value>| serde_json::to_string(r).unwrap();
            got.sort_by_key(key);
            want_rows.sort_by_key(key);
            if got != want_rows {
                let _ = writeln!(out, "{id}: rows\n  got  {got:?}\n  want {want_rows:?}");
            }
        }
        (false, Err(e)) => {
            let class = e.error_class().name();
            let want = case["error_class"].as_str().unwrap();
            let params: serde_json::Map<String, Value> = e
                .message_parameters()
                .iter()
                .map(|(k, v)| ((*k).to_owned(), Value::String(v.clone())))
                .collect();
            // The fixture's tables are temporary views in Spark, whose
            // suggestions qualify columns by the view's name; here they are
            // catalog tables, which Spark's suggestions do not qualify.
            let mut want_params = case["message_parameters"].as_object().unwrap().clone();
            if let Some(Value::String(p)) = want_params.get_mut("proposal") {
                for name in tables {
                    *p = p.replace(&format!("`{name}`."), "");
                }
            }
            if class != want || params != want_params {
                let _ = writeln!(
                    out,
                    "{id}: error {class} {params:?}\n  Spark {want} {want_params:?}"
                );
            }
        }
        (true, Err(e)) => {
            let _ = writeln!(out, "{id}: failed: {e}");
        }
        (false, Ok(_)) => {
            let _ = writeln!(out, "{id}: ran; Spark raised {}", case["error_class"]);
        }
    }
    out
}

#[test]
fn window_functions_match_spark() {
    let g = fixture();
    let s = session(&g);
    let mut report = String::new();
    let cases = g["cases"].as_array().unwrap();
    let tables: Vec<&str> = g["tables"]
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .collect();
    for case in cases {
        report.push_str(&check(&s, &tables, case));
    }
    // Every class the window code raises is matched against Spark above.
    let matched: Vec<&str> = cases
        .iter()
        .filter(|c| !c["ok"].as_bool().unwrap())
        .filter_map(|c| c["error_class"].as_str())
        .collect();
    for class in [
        "DATATYPE_MISMATCH.RANGE_FRAME_WITHOUT_ORDER",
        "DATATYPE_MISMATCH.SPECIFIED_WINDOW_FRAME_INVALID_BOUND",
        "DATATYPE_MISMATCH.VALUE_OUT_OF_RANGE",
        "DATATYPE_MISMATCH.NON_FOLDABLE_INPUT",
        "DATATYPE_MISMATCH.UNEXPECTED_INPUT_TYPE",
        "DISTINCT_WINDOW_FUNCTION_UNSUPPORTED",
        "INVALID_AGGREGATE_FILTER.CONTAINS_WINDOW_FUNCTION",
        "INVALID_SQL_SYNTAX.INVALID_WINDOW_REFERENCE",
        "INVALID_SQL_SYNTAX.UNRESOLVED_WINDOW_REFERENCE",
        "INVALID_SQL_SYNTAX.REPETITIVE_WINDOW_DEFINITION",
        "MISSING_WINDOW_SPECIFICATION",
        "MISSING_GROUP_BY",
        "MISSING_AGGREGATION",
        "NUMERIC_VALUE_OUT_OF_RANGE.WITH_SUGGESTION",
        "ARITHMETIC_OVERFLOW",
        "UNSUPPORTED_EXPR_FOR_OPERATOR",
        "UNSUPPORTED_EXPR_FOR_WINDOW",
        "UNSUPPORTED_FEATURE.LATERAL_COLUMN_ALIAS_IN_AGGREGATE_WITH_WINDOW_AND_HAVING",
        "UNSUPPORTED_FEATURE.LATERAL_COLUMN_ALIAS_IN_WINDOW",
        "WINDOW_FUNCTION_FRAME_NOT_ORDERED",
        "WINDOW_FUNCTION_NOT_ALLOWED_IN_CLAUSE",
        "WINDOW_FUNCTION_WITHOUT_OVER_CLAUSE",
        "_LEGACY_ERROR_TEMP_1031",
        "_LEGACY_ERROR_TEMP_1036",
    ] {
        assert!(matched.contains(&class), "{class} not covered");
    }
    assert!(cases.len() > 100, "the fixture lost cases");
    assert!(report.is_empty(), "mismatches against Spark:\n{report}");
}

/// A filter over a query whose `HAVING` filtered the aggregate below its
/// windows filters the windows' output, as Spark's outer filter does: the
/// same rows as an outer `WHERE`.
#[test]
fn a_second_filter_filters_the_windows_output() {
    use krishiv_session::functions::{col, lit};
    let s = session(&fixture());
    let rows = |df: krishiv_session::DataFrame| {
        let batches = block_on(df.collect()).unwrap();
        let mut out: Vec<String> = batches
            .iter()
            .flat_map(|b| {
                (0..b.num_rows()).map(|i| {
                    b.columns()
                        .iter()
                        .map(|c| text(c, i).to_string())
                        .collect::<Vec<_>>()
                        .join(",")
                })
            })
            .collect();
        out.sort();
        out
    };
    let inner = "SELECT p, sum(v) AS s, rank() OVER (ORDER BY sum(v)) AS r FROM t GROUP BY p \
                 HAVING s > 3";
    let filtered = block_on(s.sql(inner)).unwrap().filter(col("r").eq(lit(1)));
    let outer = block_on(s.sql(&format!("SELECT * FROM ({inner}) WHERE r = 1"))).unwrap();
    let got = rows(filtered);
    assert_eq!(got, rows(outer));
    // Spark 4.2: (2, 7, 1) and (1, 35, 2) before the filter.
    assert_eq!(got, ["\"2\",\"7\",\"1\""]);
}

/// A DataFrame filter over an aggregate with windows filters their output
/// (Spark 4.2.0: `df.filter(col("r") > 1)` over `rank() OVER (...) AS r`
/// returns the rows with `r > 1`), while the same predicate as a SQL
/// `HAVING` cannot name the window's alias and filters below the windows.
#[test]
fn a_dataframe_filter_sees_the_window_output_and_having_does_not() {
    use krishiv_session::functions::{col, lit};
    let s = session(&fixture());
    let select = "SELECT p, sum(v) AS s, rank() OVER (ORDER BY sum(v)) AS r FROM t GROUP BY p";
    let rows = block_on(async {
        let df = s.sql(select).await?;
        let batches = df.filter(col("r").gt(lit(1))).collect().await?;
        let mut rows = Vec::new();
        for b in &batches {
            for i in 0..b.num_rows() {
                let cells: Vec<String> = b
                    .columns()
                    .iter()
                    .map(|c| {
                        if c.is_null(i) {
                            "NULL".to_owned()
                        } else {
                            match c.data_type() {
                                DataType::Int32 => {
                                    c.as_primitive::<Int32Type>().value(i).to_string()
                                }
                                _ => c.as_primitive::<Int64Type>().value(i).to_string(),
                            }
                        }
                    })
                    .collect();
                rows.push(cells.join("|"));
            }
        }
        rows.sort();
        Ok::<_, krishiv_common::error::KrishivError>(rows)
    })
    .unwrap();
    assert_eq!(rows, ["1|35|3", "2|7|2"]);
    let err = block_on(async {
        s.sql(&format!("{select} HAVING r > 1"))
            .await?
            .collect()
            .await
    })
    .unwrap_err();
    assert_eq!(
        err.error_class().name(),
        "UNRESOLVED_COLUMN.WITH_SUGGESTION"
    );
}
